import fetch from"node-fetch";const API="https://api.escuelajs.co/api/v1";function fetchData(t){return fetch(t)}fetchData(`${API}/products`).then((t=>t.json())).then((t=>(console.log(t),fetchData(`${API}/products/${t[0].id}`)))).then((t=>t.json())).then((t=>(console.log(t.title),fetchData(`${API}/categories/${t.category.id}`)))).then((t=>t.json())).then((t=>console.log(t.name))).catch((t=>console.log(t))).finally((()=>console.log("Finally")));